        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "The opening of high-energy neutrino astronomy is a fundamental new observational window on the violent Universe.",
        "attribution": "Halzen provided decisive scientific leadership and Karle was central to the detector effort; both fit the proposed achievement.",
        "maturity": "IceCube established an astrophysical flux and has made the method credible as a lasting branch of astronomy.",
        "uncertainties": [
          "The underlying experimental achievement relied on a very large collaboration, making individual credit inevitably selective."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Heino Falcke",
        "James M. Moran",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Black-hole imaging is an exceptional instrumental and observational achievement that made a once inaccessible regime measurable.",
        "attribution": "Falcke, Moran, and Doeleman represent key conceptual, interferometric, and project leadership contributions.",
        "maturity": "Images of more than one black-hole system and extensive calibration work make the result robust.",
        "uncertainties": [
          "The collaboration is unusually broad, so any three-person attribution will omit major contributors."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping and create unusually sensitive probes of fundamental physics.",
        "attribution": "Katori's lattice-clock concept and Ye's decisive experimental development form a clear and balanced attribution.",
        "maturity": "Independent laboratories have achieved extraordinary accuracy and reproducibility over many years.",
        "uncertainties": [
          "The ultimate replacement of present time standards remains a technical and institutional process."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers created a powerful new measurement capability for matter on atomic length and ultrafast time scales.",
        "attribution": "Pellegrini, Rossbach, and Kim cover the central accelerator, facility, and theoretical foundations.",
        "maturity": "Operational facilities and a wide body of science demonstrate that this is a durable experimental platform.",
        "uncertainties": [
          "The achievement has many precursor and facility contributors, complicating a strict three-person division of credit."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP supplied a remarkably precise empirical foundation for modern cosmological parameters and early-Universe physics.",
        "attribution": "Bennett, Spergel, and Page represent the mission leadership, interpretation, and experimental realization.",
        "maturity": "Its findings have been tested against subsequent precision cosmology measurements and remain foundational.",
        "uncertainties": [
          "The scientific legacy overlaps with earlier and later cosmic-microwave-background missions."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Jian-Wei Pan"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution established a physically new approach to secure communication and stimulated a major experimental field.",
        "attribution": "Bennett and Brassard established essential protocols, while Pan led influential realization and network-scale experiments.",
        "maturity": "The field has progressed from foundational demonstrations to demanding long-distance and network experiments.",
        "uncertainties": [
          "Ekert's independent foundational contribution makes limiting recognition to three people difficult.",
          "Practical security depends on implementation details beyond the ideal protocols."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Masato Sagawa",
        "John J. Croat"
      ],
      "assessment": {
        "nobel_worthiness": "Neodymium-iron-boron magnets are a materials breakthrough with profound and enduring technological consequences.",
        "attribution": "Sagawa and Croat are the leading credited independent developers of the high-performance magnet material.",
        "maturity": "Its broad, decades-long adoption establishes both reproducibility and extraordinary practical importance.",
        "uncertainties": [
          "The advance may be judged more as a major technological materials development than a Nobel-scale physics discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals introduced a compelling way to control light through engineered band structures and enabled a broad field.",
        "attribution": "Yablonovitch and John made seminal conceptual contributions, with Joannopoulos central to the theoretical framework.",
        "maturity": "The ideas have been extensively tested and incorporated into many photonic devices and measurement approaches.",
        "uncertainties": [
          "Applications are diverse, but no single experimental consequence has the singular character of the highest-ranked discoveries."
        ]
      }
    }
  ]
